const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // Define regions - northern and southern Kenya
  const northernKenya = ee.Geometry.Polygon([
    [[34, 5], [42, 5], [42, 0], [34, 0], [34, 5]]
  ]);

  const southernKenya = ee.Geometry.Polygon([
    [[34, 0], [42, 0], [42, -5], [34, -5], [34, 0]]
  ]);

  // Time period: May-June 2019
  const startDate = '2019-05-01';
  const endDate = '2019-06-30';

  // Load MODIS NDVI data
  const modisCol = ee.ImageCollection('MODIS/006/MOD13Q1')
    .filterDate(startDate, endDate)
    .filterBounds(northernKenya.union(southernKenya));

  // Check if collection is empty
  const colSize = modisCol.size().getInfo();
  if (colSize === 0) {
    console.log(`MODIS Images: ${colSize}`);
    console.log("<answer>C1</answer>");
    return;
  }

  // Create a composite for the period and apply quality mask
  const composite = modisCol.median();

  // Extract NDVI band and scale (scale factor: 0.0001)
  const ndvi = composite.select('NDVI').multiply(0.0001);

  // Apply quality mask using DetailedQA band
  const qualityMask = composite.select('DetailedQA').bitwiseAnd(0b111111).eq(0);
  const maskedNdvi = ndvi.updateMask(qualityMask);

  // Calculate mean NDVI for both regions
  const northStats = maskedNdvi.reduceRegion({
    reducer: ee.Reducer.mean().combine({
      reducer2: ee.Reducer.count(),
      sharedInputs: true
    }),
    geometry: northernKenya,
    scale: 1000,
    maxPixels: 1e9
  });

  const southStats = maskedNdvi.reduceRegion({
    reducer: ee.Reducer.mean().combine({
      reducer2: ee.Reducer.count(),
      sharedInputs: true
    }),
    geometry: southernKenya,
    scale: 1000,
    maxPixels: 1e9
  });

  const northData = northStats.getInfo();
  const southData = southStats.getInfo();

  // Check for valid pixels
  if (northData.NDVI_count === 0 || southData.NDVI_count === 0) {
    console.log(`North pixels: ${northData.NDVI_count}, South pixels: ${southData.NDVI_count}`);
    console.log("<answer>C2</answer>");
    return;
  }

  const northNdvi = northData.NDVI_mean;
  const southNdvi = southData.NDVI_mean;

  // Validate results
  if (northNdvi === null || southNdvi === null || 
      isNaN(northNdvi) || isNaN(southNdvi) ||
      northNdvi < -1 || northNdvi > 1 || southNdvi < -1 || southNdvi > 1) {
    console.log(`Invalid NDVI values - North: ${northNdvi}, South: ${southNdvi}`);
    console.log("<answer>C3</answer>");
    return;
  }

  // Print stats and determine answer
  console.log(`North Kenya NDVI: ${northNdvi.toFixed(3)} (pixels: ${northData.NDVI_count})`);
  console.log(`South Kenya NDVI: ${southNdvi.toFixed(3)} (pixels: ${southData.NDVI_count})`);
  console.log(`Images in period: ${colSize}`);

  if (northNdvi < southNdvi) {
    console.log("<answer>A</answer>");
  } else {
    console.log("<answer>B</answer>");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
